window.JIREH_CANON={"version":"1.0.0","lastReviewed":"2026-09-12","firm":{"name":"Jireh Strategies","tagline":"The Multiplication of Community Assets","principal":"Hakeem Abbu","titles":["Owner & Principal, Jireh Strategies","Development Director, Adult & Teen Challenge Dallas"],"closing":"Soli Deo Gloria","positioning":"The accelerator of the community asset incubator.","category":"Identifying, underwriting, and capitalizing community-asset production."},"product":{"name":"A Community Asset","definition":"A human being whose productive capacity has been identified, developed, connected to opportunity, and verified, and who now produces value in a place that was previously charged for their absence.","notAService":"A service is consumed and gone; it must be purchased again next year at the same price for the same result. A community asset appreciates.","proofOfProduct":["Earned income","A held job","A stable home","A child who is watched","A neighbor who is carried"]},"pillars":[{"id":"measurable-impact","label":"Measurable Impact","shortProof":"Certified by eight witnesses, none of them ours.","conventional":"The conventional standard is self-reported output.","ours":"Certification by eight independent parties — participant, clinician, lease, credentialing body, employer, family, congregation, and the person they went on to develop — none of whom work for us, and any of whom can invalidate the claim."},{"id":"sustainability","label":"Sustainability","shortProof":"Assets that outlive the money that made them.","conventional":"The conventional question is whether the organization survives the funding.","ours":"Whether the community assets created by the funding keep producing after the funding is gone — and whether the capability that produced them stayed in the building."},{"id":"scalability","label":"Scalability","shortProof":"Not more programs; more producers.","conventional":"The conventional question is whether it opens more sites.","ours":"Whether the system reproduces inside organizations we will never operate and in people we will never meet — which costs almost nothing per unit and never stops."}],"eightWitnesses":["The participant","The clinician","The lease","The credentialing body","The employer","The family","The congregation","The person they went on to develop"],"offer":{"name":"The Capital Partnership","structure":"Retained · Annual · A position, not a project","priceUSD":28000,"priceDisplay":"$28,000","priceCadence":"annually","unit":"One organization · One standing position","term":"One year","rationale":"Held as a standing position because institutional capital matures over twenty-four to forty-eight months, and no honest fundraiser promises otherwise.","anchor":{"claim":"Twenty-eight thousand dollars is less than the State of Texas spends to incarcerate one person for one year.","comparisonValueUSD":28300,"comparisonLabel":"Incarceration, per person, per year in Texas"},"exclusions":["There is no second invoice.","There is no per-proposal fee.","There is no percentage of anything raised.","Jireh Strategies does not accept contingent compensation. The profession's ethical standards prohibit it, and a flat retained fee means the counsel you receive is the counsel I would give if no gift ever closed."],"deliberatelySingular":"Not a menu priced by the page, not an entry-level diagnostic that must be upsold before it does anything, and not a contingent arrangement that quietly pays more when the fastest dollar is chased instead of the right one."},"offerComponents":[{"order":"ONE","verb":"IDENTIFY","title":"Asset identification and capital readiness","body":"Everything the organization already owns, inventoried, valued, and mapped to what it produces — most of it named for the first time."},{"order":"TWO","verb":"UNDERWRITE","title":"Underwriting and proposal architecture","body":"The business case, the financial framing, the outcome measurement, and the sustainability and scalability analysis funders now require."},{"order":"THREE","verb":"CARRY","title":"Pipeline, cultivation and stewardship","body":"Funders researched, qualified and matched; solicitations carried; reporting that renews the gift rather than closing the file."}],"organizationalAssets":[{"id":"intelligence","name":"The Intelligence","subtitle":"Seeing what is already there","body":"Continuous funder and opportunity research paired with organizational asset identification — determining what an organization already owns, what measurable value it produces, and what additional capital would activate. Most organizations have never had this done for them once."},{"id":"architecture","name":"The Architecture","subtitle":"Making it underwritable","body":"Project development, business planning, financial and operational framing, outcome measurement, sustainability and scalability analysis — the conversion of daily practice into an institutional investment case a committee can act on rather than admire."},{"id":"carriage","name":"The Carriage","subtitle":"Bringing the capital back","body":"Donor positioning, partnership development, cultivation, solicitation and stewardship — the case carried into the rooms where capital is actually released, by someone who has been believed in those rooms before."}],"cascade":[{"stage":"STAGE ONE","title":"Capital Placed","detail":"into Jireh's organizational assets"},{"stage":"STAGE TWO","title":"Accelerator Capacity","detail":"research, underwriting, advocacy"},{"stage":"STAGE THREE","title":"Incubators Capitalized","detail":"organizations funded to expand"},{"stage":"STAGE FOUR","title":"Potential Activated","detail":"gifts identified and developed"},{"stage":"STAGE FIVE","title":"Community Assets","detail":"wages, homes, families, giving"},{"stage":"STAGE SIX","title":"Replication","detail":"each asset produces the next"}],"incubatorAssets":["Housing & facilities","Staff expertise & case management","Curriculum & training capacity","Employer & workforce relationships","Transportation & access","Congregational & community trust","Volunteers & alumni networks","Equipment & social enterprises","Direct access to the unreached"],"marketSize":[{"value":"$617.2B","label":"U.S. charitable giving, 2025 — a record year","source":"Giving USA 2026, Lilly Family School of Philanthropy"},{"value":"$117.2B","label":"Foundation giving, 2025 (up 5.7% year over year)","source":"Giving USA 2026"},{"value":"$251B+","label":"Held in donor-advised funds, awaiting deployment","source":"National Philanthropic Trust DAF Report"},{"value":"$1.571T","label":"Global impact capital hunting for underwritable vehicles","source":"Global Impact Investing Network market sizing"}],"costOfInaction":[{"value":"$28,300","label":"Incarceration, per person, per year in Texas"},{"value":"$15,000+","label":"Emergency rooms, shelters, and jails, per person, per year"},{"value":"$4 health · $7 justice","label":"Returned by sustained recovery, for every $1 invested"},{"value":"$6,900 – $33,500","label":"Saved by supportive housing, per person, per year"},{"value":"Unrealized Human Potential","label":"The greatest cost, and the one nobody invoices for"}],"capitalAlreadyMoved":["The Stoller Foundation","The Christ Foundation","The David Scaife Foundation","The Texas Housing Corporation","Walmart Spark Good","The Kennedy Memorial Foundation"],"criticalProblem":"The absence of the infrastructure required to convert what an organization is already doing into an underwritable investment opportunity.","moneyLine":"Money is not scarce in this country. Translation is.","reframe":{"weak":"Help this organization cover its expenses.","strong":"Capitalize the productive infrastructure that converts individual potential into measurable community value.","note":"One of those is a request. The other is an investment thesis, and only one of them survives a trustee who asks a second question."},"assetTranslations":[{"expense":"A transportation line item","capacity":"Access infrastructure"},{"expense":"A case manager","capacity":"Navigation and stabilization infrastructure"},{"expense":"A training instructor","capacity":"Human-capital development infrastructure"},{"expense":"An employer partnership","capacity":"Economic deployment infrastructure"},{"expense":"An alumni program","capacity":"Replication infrastructure"}]};
window.JIREH_PAYOFFS={"version":"1.0.0","doctrine":"The client is not buying pages. They are buying accelerated access to capital.","reframe":{"weak":"Help this organization cover its expenses.","strong":"Capitalize the productive infrastructure that converts individual potential into measurable community value.","verdict":"One of those is a request. The other is an investment thesis, and only one of them survives a trustee who asks a second question."},"payoffs":[{"id":"named","sequence":1,"component":"IDENTIFY","feature":"Asset identification and capital readiness","headline":"Everything you own, named for the first time.","youGet":"A written inventory of every productive asset in your organization — housing, staff expertise, curriculum, employer relationships, transportation, congregational trust, alumni networks, equipment, access — each valued and mapped to what it produces.","whatChanges":"You stop describing what you spend and start demonstrating what you own. Most organizations have never had this done for them once.","proofPoint":"Nine asset classes, inventoried and priced.","emotionalPayoff":"The relief of finally seeing on paper what you have always known was there.","timing":"Months 1–3"},{"id":"translated","sequence":2,"component":"IDENTIFY","feature":"Underwriter translation","headline":"Your line items, rewritten in the language capital reads.","youGet":"Every expense reframed as the capacity it sustains. A transportation line becomes access infrastructure. A case manager becomes navigation and stabilization infrastructure. An alumni program becomes replication infrastructure.","whatChanges":"A committee stops reading your budget as a cost and starts reading it as a production process.","proofPoint":"Expense → capacity → what that capacity produces → the return.","emotionalPayoff":"Being understood by people who have been declining you for years.","timing":"Months 1–3"},{"id":"provable","sequence":3,"component":"UNDERWRITE","feature":"Outcome architecture and the eight witnesses","headline":"Claims that survive a trustee who asks a second question.","youGet":"An outcome measurement architecture where every claim is certified by independent parties — participant, clinician, lease, credentialing body, employer, family, congregation, and the person they went on to develop. None of them work for us. Any of them can invalidate the claim.","whatChanges":"You stop submitting self-reported output and start submitting verified production. That is the difference between a story and an underwritable asset.","proofPoint":"Eight independent verifiers per claim.","emotionalPayoff":"Walking into diligence without bracing for the question you cannot answer.","timing":"Months 2–6"},{"id":"underwritable","sequence":4,"component":"UNDERWRITE","feature":"Business case, financial framing, sustainability and scalability analysis","headline":"An investment case a committee can act on rather than admire.","youGet":"The full institutional package: the business case, the financial and operational framing, the cost-offset model, and the sustainability and scalability analysis funders now require and most applicants cannot produce.","whatChanges":"Your proposal stops competing on sympathy and starts competing on return. You become one of the few vehicles in your region that institutional capital can actually underwrite.","proofPoint":"The three questions every committee asks second — sustainability, scalability, measurability — answered before they are asked.","emotionalPayoff":"Being taken seriously by the room you have always been outside of.","timing":"Months 3–8"},{"id":"pipeline","sequence":5,"component":"CARRY","feature":"Funder research, qualification and matching","headline":"A managed pipeline instead of a lottery.","youGet":"Continuous funder and opportunity research: foundations, family offices, donor-advised funds, corporate givers, public payers and settlement streams — researched, qualified, and matched to what you specifically produce.","whatChanges":"Capital stops feeling like a lottery and starts behaving like a process with stages, criteria and a forecast.","proofPoint":"Opioid settlement funds, Medicaid recovery supports, workforce initiatives, second-chance coalitions. Every one pays for documented production.","emotionalPayoff":"Knowing what happens next month, and the month after.","timing":"Months 2–12, continuous"},{"id":"carried","sequence":6,"component":"CARRY","feature":"Cultivation, solicitation and stewardship","headline":"The case carried into rooms you cannot currently enter.","youGet":"Donor positioning, partnership development, cultivation, solicitation and the stewardship that renews the gift rather than closing the file — carried by someone who has been believed in those rooms before.","whatChanges":"You stop submitting into a portal and hoping. Someone with standing is in the room arguing your case.","proofPoint":"Capital has already moved on this judgment, from institutions that give at the highest level.","emotionalPayoff":"Not being alone in it anymore.","timing":"Months 4–12, continuous"},{"id":"installed","sequence":7,"component":"ALL THREE","feature":"A capability that stays after the year ends","headline":"A methodology does not resign.","youGet":"The system installed inside your organization: written down, teachable, and surviving the person who taught it. Structural capacity rather than heroic capacity.","whatChanges":"Average development director tenure is roughly sixteen months. The median vacancy takes six months to fill. Replacement runs near $130,000. What you install here does not leave.","proofPoint":"$28,000 for a standing capability, against ~$130,000 to replace a director who lasted sixteen months.","emotionalPayoff":"Building something that outlasts you — which is the whole reason you do this work.","timing":"Permanent"}],"outcomeStack":[{"order":1,"label":"You know what you own","detail":"Every asset inventoried and valued."},{"order":2,"label":"You can prove what it produces","detail":"Certified by eight independent witnesses."},{"order":3,"label":"Capital can evaluate you","detail":"An investment case, not a request."},{"order":4,"label":"Capital moves","detail":"Carried into the rooms where it is released."},{"order":5,"label":"Capacity expands","detail":"Staff hired, facilities built, programs opened."},{"order":6,"label":"More community assets are produced","detail":"Potential identified, developed, deployed, verified."},{"order":7,"label":"They produce the next ones","detail":"Within twelve to twenty-four months, most turn and do for somebody else exactly what was done for them."}],"objections":[{"objection":"We cannot afford $28,000.","answer":"Twenty-eight thousand dollars is less than the State of Texas spends to incarcerate one person for one year. That is the comparison this venture invites, because it is the honest one. The question is not whether the money is spent — it is being spent right now, downstream, against the same people, purchasing nothing that survives the fiscal year. The only live question is whether a fraction of it is redirected upstream to the machinery that would have prevented the invoice."},{"objection":"We should just hire a development director.","answer":"Average tenure is roughly sixteen months. The median vacancy takes six months to fill. Replacement runs near $130,000, and half plan to leave within two years. A methodology does not resign. It is written down, installed in the organization, and survives the person who taught it — which is the definition of structural rather than heroic capacity."},{"objection":"Can you work on contingency, a percentage of what you raise?","answer":"No, and the refusal is the point. The profession's ethical standards prohibit it, and a flat retained fee means the counsel you receive is the counsel I would give if no gift ever closed. Contingent arrangements quietly pay more when the fastest dollar is chased instead of the right one. There is no second invoice, no per-proposal fee, and no percentage of anything raised."},{"objection":"We already have a grant writer.","answer":"A grant writer produces an application and inherits whatever evidence you already have. When the contract ends, nothing has been built. We identify and build the asset case before writing a word about it — the proposal is the last step, not the only one, and the capability remains after the invoice is paid."},{"objection":"How fast will we see money?","answer":"Institutional capital matures over twenty-four to forty-eight months, and no honest fundraiser promises otherwise. That is precisely why this is held as a standing annual position rather than a project. The opening months are spent learning what you own; every month afterward is spent converting it — which is why the same fee buys more capital in the second year than the first, and more again in the third."},{"objection":"Why should we believe this works?","answer":"Capital has already moved on this judgment, from foundations giving at the highest level. The methodology has been run against live organizations, real participants and real capital. And the central claim — that a developed person develops others — was proven at national scale by an industry that did not notice it was proving anything: certified peer support specialists grew from about 30,000 to about 82,000 in a decade. Nobody marketed that. It reproduced."}]};
window.JIREH_SEGMENTS={"version":"1.0.0","axis":"Capital readiness — because readiness, not revenue, determines what an organization needs and what it will pay for.","universalPain":"It is almost never 'we need someone to write a grant.' It is always, underneath, 'we know exactly what we could accomplish, and we do not have the capital to accomplish it.'","universalPurchase":"The same purchase in every row: accelerated access to the capital their assets already justify.","tiers":[{"id":"emerging","name":"Emerging organizations","keepsThemAwake":"A strong mission concept and no fundraising infrastructure whatsoever. Capital feels like a lottery rather than a process.","actuallyBuying":"Organizational development, project design, funding research, and a first credible capital strategy.","posture":"Entry point. Buys clarity, then buys capability.","payoffHeadline":"Stop treating capital like a lottery."},{"id":"undercapitalized","name":"Established but undercapitalized","keepsThemAwake":"Delivering real services daily and absorbing a shortfall that earned revenue should have covered years ago. Their best work is invisible to funders.","actuallyBuying":"Institutional fundraising, asset identification, outcome measurement, and a business case strong enough to expand on.","posture":"Value-sensitive, not price-sensitive. Buys capability.","payoffHeadline":"Your best work is invisible. That is a translation problem, not a merit problem."},{"id":"growth","name":"Growth-stage organizations","keepsThemAwake":"A new facility, campus, housing development, workforce initiative or social enterprise with no financing architecture behind it.","actuallyBuying":"Sophisticated underwriting and a coordinated capital strategy across philanthropic, public, corporate and private sources.","posture":"Buys on return. Highest urgency in the market.","payoffHeadline":"You have the project. What is missing is the financing architecture behind it."},{"id":"network","name":"Mature institutions & networks","keepsThemAwake":"Uneven quality across affiliates, new initiatives without a funding thesis, and no shared instrument to compare one site to another.","actuallyBuying":"Special-initiative underwriting, replication strategy, and a common standard defensible across the whole network.","posture":"Multi-site engagement. Highest lifetime value in the venture.","payoffHeadline":"One standard, defensible across every affiliate you have."},{"id":"funder","name":"Foundations, family offices & DAF holders","keepsThemAwake":"More capital than underwritable pipeline, and positions they cannot defend if a trustee presses hard.","actuallyBuying":"Diligence they do not have to staff, and a verdict on community-asset production they can act on.","posture":"Wholly convenience- and confidence-driven.","payoffHeadline":"More capital than underwritable pipeline is not a giving problem. It is a diligence problem."}],"overlookedSegment":{"name":"The Segment Everyone Is Ignoring","claim":"There is a category of organization in this country that possesses something no consultancy can manufacture and no foundation can buy: trusted, standing access to the people everyone else is trying to reach.","examples":["Churches operating recovery and reentry work","Neighborhood ministries","Family-support outfits","Rescue missions","Vocational programs run out of donated buildings"],"whyOverlooked":"They lack professional development departments, institutional research capacity, data systems, and the language sophisticated funders require. So the capital passes over them and lands on institutions with better grammar and worse access.","thesis":"That is the single largest pool of unpriced community-asset production in the American economy, and it is sitting in plain view.","closingLine":"Nobody is failing to fund these organizations because the work is weak. They are failing because the work has never been translated."}};
window.JIREH_CATEGORIES={"version":"1.0.0","categories":[{"id":"church-recovery","name":"Churches Running Recovery & Reentry Work","slug":"churches-recovery-reentry","overlooked":true,"holds":["Congregational trust","Volunteer networks","Facilities that sit empty six days a week","Direct access to people nobody else reaches"],"pain":"You are producing restored lives every week and reporting attendance. The capital markets cannot read attendance.","hook":"A congregation is a distribution network with a building attached. No foundation can buy what you already have."},{"id":"rescue-mission","name":"Rescue Missions & Neighborhood Ministries","slug":"rescue-missions","overlooked":true,"holds":["Beds and facilities","Meal and shelter capacity","Decades of community standing","Alumni who never left the neighborhood"],"pain":"Your donor base is aging and your bed nights are rising. Those two lines cross, and everyone in the building knows the year.","hook":"You are the last institution standing in some of these neighborhoods. That is an asset with a price nobody has calculated."},{"id":"recovery-program","name":"Recovery, Treatment & Residential Programs","slug":"recovery-treatment-programs","overlooked":true,"holds":["Clinical and peer staff","Residential capacity","Curriculum","Credentialing pathways"],"pain":"Sustained recovery returns four dollars in health costs and seven in justice costs for every dollar invested. You have never once put that on a page a funder reads.","hook":"Opioid settlement funds are flowing to counties with an abatement mandate and no vehicles able to receive them. You are the vehicle."},{"id":"workforce","name":"Workforce, Vocational & Second-Chance Employment","slug":"workforce-second-chance","overlooked":true,"holds":["Employer relationships","Training capacity","Placement pipelines","Retention data nobody has asked you for"],"pain":"State workforce programs underwrite employer-side efforts that require retention data almost no provider can supply. You have the data and no way to present it.","hook":"Imprisonment reduces lifetime earnings by 51.7 percent. You reverse that. Nobody has ever priced the reversal."},{"id":"housing-reentry","name":"Housing, Shelter & Reentry Operators","slug":"housing-reentry-operators","overlooked":true,"holds":["Units and leases","Case management","Landlord relationships","Supportive services"],"pain":"Supportive housing saves between $6,900 and $33,500 per person per year. You produce that saving and invoice nobody for it.","hook":"A lease in a formerly homeless person's name is an independently verifiable outcome. You already generate them. Start counting them as production."},{"id":"network","name":"Denominational Networks & Multi-Site Associations","slug":"denominational-networks","overlooked":false,"holds":["Dozens of affiliates","A shared brand","Aggregate reach no single site can claim","Uneven quality nobody can measure"],"pain":"You cannot compare one site to another because no shared instrument exists. Neither can your funders, which is why they fund none of you at scale.","hook":"One standard, defensible across every affiliate. That is a network-level asset and it is worth more than any single grant."},{"id":"social-enterprise","name":"Social Enterprises & Earned-Revenue Ministries","slug":"social-enterprises","overlooked":true,"holds":["Equipment and inventory","Revenue history","Employment capacity","A sustainability story already half-written"],"pain":"You have the sustainability argument every committee asks for and you have never framed it as one.","hook":"Earned revenue is the answer to the question every trustee asks second. You already have the answer."},{"id":"foundation","name":"Foundations, Family Offices & DAF Holders","slug":"foundations-family-offices","overlooked":false,"holds":["Capital","A mandate","Trustees who ask hard questions","No pipeline that survives them"],"pain":"You hold more capital than underwritable pipeline, and positions you cannot defend if a trustee presses hard.","hook":"Diligence you do not have to staff, and a verdict on community-asset production you can act on."}]};
